#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>

int main(int argc, char* argv[]) {
    int opt;
    while ((opt = getopt(argc, argv, "hvf:")) != -1) {
        switch (opt) {
            case 'h': printf("Help menu\n"); return 0;
            case 'v': printf("Version 1.0.0\n"); return 0;
            case 'f': printf("File: %s\n", optarg); break;
            default: fprintf(stderr, "Usage: %s [-h] [-v] [-f file]\n", argv[0]); return 1;
        }
    }
    return 0;
}

#include <stdio.h>
#include <stdlib.h>
#include <string.h>

int main(void) {
    char line[256];
    printf("dTyp interactive shell. Type 'exit' to quit.\n");
    while (1) {
        printf("> ");
        if (!fgets(line, sizeof(line), stdin)) break;
        line[strcspn(line, "\r\n")] = 0;
        if (strcmp(line, "exit") == 0) break;
        printf("Received: %s\n", line);
    }
    return 0;
}

#include <stdio.h>
#include <time.h>

int main(void) {
    struct timespec start, end;
    clock_gettime(CLOCK_MONOTONIC, &start);

    /* Workload under test */
    for (volatile long i = 0; i < 10000000L; i++);

    clock_gettime(CLOCK_MONOTONIC, &end);
    double elapsed = (end.tv_sec - start.tv_sec) + (end.tv_nsec - start.tv_nsec) / 1e9;
    printf("Elapsed time: %.6f seconds\n", elapsed);
    return 0;
}

