typedef struct {
    unsigned char buffer[64 * 1024];
    size_t offset;
} arena_allocator_t;

static arena_allocator_t g_arena;

void* arena_alloc(size_t size) {
    size_t aligned = (size + 7) & ~7;
    if (g_arena.offset + aligned > sizeof(g_arena.buffer)) return NULL;
    void* ptr = &g_arena.buffer[g_arena.offset];
    g_arena.offset += aligned;
    return ptr;
}

void arena_reset(void) {
    g_arena.offset = 0;
}

